static inline int kref_sub(struct kref *kref, unsigned int count, /* <=== kref_sub */ 
	     void (*release)(struct kref *kref))
{
	WARN_ON(release == NULL);

	if (atomic_sub_and_test((int) count, &kref->refcount)) {
		release(kref);
		return 1;
	}
	return 0;
}

